head.script:
// 테스트 설명, 유효성 값 설정
//  - 본 샘플(_2)은 ignoreNonEditableCellTabEnter 가 '미적용'되는 조건을 검증한다.
//    · focusMove 속성으로 키보드 포커스 이동이 차단되면 적용되지 않음 (@description |)
//    · useShiftKey=true 로 Shift+방향키 선택 처리 시에는 적용되지 않음 (@propval true |)
//  - 전제: ignoreNonEditableCell=true + ignoreNonEditableCellTabEnter=true 고정
//    (원래 상/하 방향키로 readonly 셀에 이동을 허용하는 상태를 만든 뒤 '미적용' 조건을 검증)
scwin.tData = {
    "description" : "[gridView > P > ignoreNonEditableCellTabEnter]<br/>상/하 방향키를 통한 포커스 이동 시 읽기전용(readonly) 상태인 Body Cell 로 이동을 허용할지 설정합니다.",
    "validation" : [
        "focusMove 속성에 의해 키보드를 통한 포커스 이동이 차단되면 ignoreNonEditableCellTabEnter 속성은 적용되지 않습니다.",
        "useShiftKey=true 일때 Shift, 방향키 조합으로 선택 처리 시에는 적용되지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1(gdl_boolean)은 초기 selectedIndex 미적용 → 기본값 명시 설정
    //  - focusMove / useShiftKey 는 '미설정'(코드 '1') 을 기본으로 두고, 사용자가 값 선택 후 Target 재생성으로 검증
    con_focusMove.setValue("1");
    con_useShiftKey.setValue("1");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - ignoreNonEditableCell=true + ignoreNonEditableCellTabEnter=true 고정 (전제)
//  - con_focusMove   : 공통 gdl_boolean → getText() ('false' 로 키보드 포커스 이동 차단 → 미적용 검증)
//  - con_useShiftKey : 공통 gdl_boolean → getText() ('true' 면 Shift+방향키 선택 시 미적용 검증)
//  - focusMode="cell" 고정      : 키보드 셀 포커스 이동 확인용
//  - Row 1, Row 3 = readOnly 로 고정 (편집 가능 행: 0, 2, 4, 5)
//    → col1 에서 아래 방향키로 이동 시 readonly 행(row1)에 도달하는 상/하 방향키 시나리오
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let vFocusMove   = con_focusMove.getText();
    let vUseShiftKey = con_useShiftKey.getText();

    // focusMode 는 키보드 포커스 이동 확인을 위해 cell 고정
    // ignoreNonEditableCell + ignoreNonEditableCellTabEnter 는 true 고정 (전제)
    // readOnlyBackgroundColor(#D3D3D3 연회색) : readonly 셀(Row1/Row3) 시각 구분 (형제 샘플과 색상 통일)
    // disabledBackgroundColor(#FFF9C4 연노랑) : disabled 셀(Row5) 시각 구분
    let properties = {
        focusMode : "cell",
        ignoreNonEditableCell : true,
        ignoreNonEditableCellTabEnter : true,
        readOnlyBackgroundColor : "#D3D3D3",
        disabledBackgroundColor : "#FFF9C4"
    };

    // focusMove : '' 미설정 시 속성 제외(기본 true). 'false' 면 키보드 포커스 이동 차단
    if (vFocusMove === 'true') {
        properties.focusMove = "true";
    } else if (vFocusMove === 'false') {
        properties.focusMove = "false";
    }

    // useShiftKey : 'true' 면 Shift+방향키 범위 선택 활성 (미적용 검증), '' 미설정 시 속성 제외(기본 false)
    if (vUseShiftKey === 'true') {
        properties.useShiftKey = true;
    } else if (vUseShiftKey === 'false') {
        properties.useShiftKey = false;
    }

    let cList = $c.gcm.createCList(properties);

    let lblDesc = '[전제] ignoreNonEditableCell=true + ignoreNonEditableCellTabEnter=true 고정'
        + ', Row1/Row3=readOnly(#D3D3D3 회색), Row5=disabled(#FFF9C4 노랑) (편집 가능 행: 0, 2, 4)'
        + '\n[현재] focusMove=' + (vFocusMove === '' ? '(미설정=기본 true)' : vFocusMove)
        + ', useShiftKey=' + (vUseShiftKey === '' ? '(미설정=기본 false)' : vUseShiftKey)
        + '\n[절차A: focusMove 차단] focusMove=false 로 재생성 후 (0,0) 셀 클릭 -> 아래 방향키 : 포커스 이동 자체가 차단되어 readonly 이동 허용 미적용'
        + '\n[절차B: useShiftKey] useShiftKey=true 로 재생성 후 (0,0) 셀 클릭 -> Shift+아래 방향키 : 선택 범위 처리(readonly 이동 허용 미적용)'
        + '\n[확인] 하단 이동 로그(oncellindexchange) 와 [선택 포커스 확인] 버튼 출력';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // 포커스 이동 확인용 dataList 생성 (col1~col4, 6행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // target 생성 (4컬럼 Body 그리드)
    await scwin.createGridView(cList);

    // Row 1, Row 3 = readOnly 설정 (상/하 방향키로 readonly 행에 도달하는 수직 이동 시나리오)
    target1.setRowReadOnly(1, true);
    target1.setRowReadOnly(3, true);

    // Row 5 = disabled 설정 (disabledBackgroundColor 시각 구분 대상)
    target1.setRowDisabled(5, true);

    // 첫번째 편집 가능 셀(row0, col0)에 셀 선택 포커스(비편집 모드)
    //  - 방향키 셀 네비게이션은 비편집 모드에서만 동작하므로 편집 진입(true) 대신 false 로 셀만 포커스
    target1.setFocusedCell(0, 0, false);
}



// 포커스 이동 확인용 데이터 (6행)
scwin.fillData = function () {
    let rows = [
        { col1: "A1", col2: "B1", col3: "C1", col4: "D1" },
        { col1: "A2", col2: "B2", col3: "C2", col4: "D2" },
        { col1: "A3", col2: "B3", col3: "C3", col4: "D3" },
        { col1: "A4", col2: "B4", col3: "C4", col4: "D4" },
        { col1: "A5", col2: "B5", col3: "C5", col4: "D5" },
        { col1: "A6", col2: "B6", col3: "C6", col4: "D6" }
    ];
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성
//  - oncellindexchange : Tab/Enter/방향키 등으로 포커스 셀이 실제 이동할 때마다 발생
//    (focusMove=false 로 이동이 차단되면 발생하지 않음 → 이동 로그로 미적용 확인)
scwin.createGridView = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:520px;height:300px;" ev:oncellindexchange="scwin.target1_oncellindexchange">';
    s += '<w2:caption style="" id="caption1" value="ignoreNonEditableCellTabEnter 미적용 조건 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 셀 포커스가 실제 이동(변경)될 때 호출 (oncellindexchange)
//  - focusMove=false 로 이동이 차단되면 이 이벤트가 발생하지 않음(로그 없음) → 미적용
//  - focusMove 미적용(기본 true) 상태에서 아래 방향키 시 readonly 행(row1)으로 이동하면
//    ignoreNonEditableCellTabEnter=true 로 상/하 방향키의 readonly 이동이 허용된 것
scwin.target1_oncellindexchange = function (rowIndex, columnIndex, oldRow, oldColumnIndex) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("oncellindexchange 발생 -> 이동 셀 (row: " + rowIndex + ", col: " + columnIndex
        + "), 이전 셀 (row: " + oldRow + ", col: " + oldColumnIndex + ")");
}



// 선택/포커스 확인 (useShiftKey=true + Shift+방향키 미적용 검증용)
//  - (0,0) 셀 클릭 후 Shift+아래 방향키 로 범위 선택한 뒤 호출.
//  - getAllFocusedIndex() 로 선택된 Cell 의 {row, col} 목록과 개수를 출력.
//  - 화면 선택 여부는 focusedTd 클래스가 적용된 <td> 개수로 확인.
//  - useShiftKey=true : Shift+방향키가 선택 범위 처리로 동작하여 readonly 이동 허용(TabEnter) 미적용
//    반대로 shift 없이 일반 방향키만 이동하면 readonly 행으로의 이동 허용(적용)을 이동 로그로 확인.
scwin.btn_checkFocused_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[옵션] ignoreNonEditableCell=" + target1.options.ignoreNonEditableCell
        + ", ignoreNonEditableCellTabEnter=" + target1.options.ignoreNonEditableCellTabEnter
        + ", focusMove=" + target1.options.focusMove
        + ", useShiftKey=" + target1.options.useShiftKey);

    // 내부 포커스(선택) 인덱스 목록
    let focused = target1.getAllFocusedIndex();
    bottom.setReturnValue("getAllFocusedIndex : " + JSON.stringify(focused));

    // 화면에 실제 선택 표시(focusedTd)된 Cell 개수
    let focusedTds = document.querySelectorAll("td[id*='mf_target1_cell_'].focusedTd");
    bottom.setReturnValue("화면 선택(focusedTd) Cell 개수 : " + focusedTds.length);
}
